-- ExcursiaConnect's first schema (backend-plan.md, M0.2). Generated by Prisma, with the extensions first and,
-- at the end, what Prisma cannot express.

-- Both are trusted extensions: the migrator, as the database's owner, may create them.
CREATE EXTENSION IF NOT EXISTS citext;     -- case-insensitive emails
CREATE EXTENSION IF NOT EXISTS btree_gist; -- equality inside the exclusion constraint below

