-- ---------------------------------------------------------------------------------------------------------------
-- What Prisma cannot express
-- ---------------------------------------------------------------------------------------------------------------

-- No room, table or person double-booked: two active busy rows with the same key may not overlap in time, however
-- many requests arrive at once (the PRD's 50-request burst). Lapsed proposals are set inactive before a booking.
ALTER TABLE "dr_busy" ADD CONSTRAINT "dr_busy_no_overlap"
  EXCLUDE USING gist ("event_id" WITH =, "key" WITH =, "slot" WITH &&) WHERE ("active");
ALTER TABLE "dr_busy" ADD CONSTRAINT "dr_busy_slot_bounded" CHECK (NOT isempty("slot") AND NOT lower_inf("slot") AND NOT upper_inf("slot"));

-- Meetings and sessions end after they start
ALTER TABLE "dr_meeting" ADD CONSTRAINT "dr_meeting_time_order" CHECK ("ends_at" > "starts_at");
ALTER TABLE "dr_session" ADD CONSTRAINT "dr_session_time_order" CHECK ("ends_at" > "starts_at");

-- A badge code is unique whatever its case, so a scanner's lowercase input finds exactly one badge
CREATE UNIQUE INDEX "badge_code_lower_key" ON "badge" (lower("code"));

-- Open opportunities by owner, for the owner's digest and overdue checks
CREATE INDEX "dr_opportunity_open_by_owner_idx" ON "dr_opportunity" ("event_id", "owner_id") WHERE NOT "closed";

-- The worker's queue: only messages still to send
CREATE INDEX "outbox_message_due_idx" ON "outbox_message" ("next_attempt_at") WHERE "status" IN ('queued', 'failed');

-- Counters only go up from zero
ALTER TABLE "dr_counter" ADD CONSTRAINT "dr_counter_not_negative" CHECK ("n" >= 0);

-- The audit log is append-only for the app and the worker. The roles exist wherever scripts/db/setup-local.sh
-- (or the server's provisioning) has run; elsewhere, such as a throwaway database, there is nothing to revoke.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'excursia_app') THEN
    REVOKE UPDATE, DELETE, TRUNCATE ON "audit_entry" FROM excursia_app;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'excursia_worker') THEN
    REVOKE UPDATE, DELETE, TRUNCATE ON "audit_entry" FROM excursia_worker;
  END IF;
END $$;
